use super::*;
use bollard::container::{
    Config, CreateContainerOptions, KillContainerOptions, LogOutput, LogsOptions,
    RemoveContainerOptions, WaitContainerOptions,
};
use bollard::models::HostConfig;
use bollard::Docker;
use futures_util::StreamExt;
use std::collections::HashMap;
use std::time::{Duration, Instant};

/// Docker's default seccomp profile minus raw wall-clock reads (generated by
/// `scripts/gen_seccomp.py`): a strategy that bypasses libfaketime with a direct
/// syscall gets EPERM instead of the real date.
pub const SECCOMP_PROFILE: &str = include_str!("../../../../deploy/seccomp/cmsq-runner.json");

/// Docker backend via bollard. Hardening applied to every container:
/// NetworkMode=none + network_disabled, read-only rootfs, CapDrop=ALL,
/// no-new-privileges, non-root user (the uid owning the job's /out dir, never 0;
/// falls back to 10001), pids/memory(no swap)/cpu limits,
/// tmpfs /tmp (noexec), only `/out` writable, never the docker socket, hard timeout
/// (kill + force remove).
/// Run as the (unprivileged, non-root) owner of the writable `/out` mount so no
/// world-writable directories are needed; never root.
pub fn run_as_user(req: &SandboxRequest) -> String {
    use std::os::unix::fs::MetadataExt;
    req.mounts
        .iter()
        .find(|m| !m.read_only)
        .and_then(|m| std::fs::metadata(&m.host).ok())
        .map(|md| (md.uid(), md.gid()))
        .filter(|(u, _)| *u != 0)
        .map(|(u, g)| format!("{u}:{g}"))
        .unwrap_or_else(|| "10001:10001".into())
}

pub struct DockerSandboxExecutor {
    docker: Docker,
}

/// Futures executing a job can be cancelled at any await point. Keep cleanup
/// independent of that future once the daemon has returned a container id.
struct ContainerCleanup {
    docker: Docker,
    id: String,
    armed: bool,
}

impl Drop for ContainerCleanup {
    fn drop(&mut self) {
        if !self.armed {
            return;
        }
        if let Ok(runtime) = tokio::runtime::Handle::try_current() {
            let docker = self.docker.clone();
            let id = self.id.clone();
            runtime.spawn(async move {
                let _ = docker
                    .remove_container(
                        &id,
                        Some(RemoveContainerOptions {
                            force: true,
                            ..Default::default()
                        }),
                    )
                    .await;
            });
        }
    }
}

impl DockerSandboxExecutor {
    pub async fn connect() -> Result<Self, SandboxError> {
        let docker = Docker::connect_with_local_defaults()
            .map_err(|e| SandboxError::Unavailable(e.to_string()))?;
        docker
            .ping()
            .await
            .map_err(|e| SandboxError::Unavailable(format!("docker ping failed: {e}")))?;
        Ok(Self { docker })
    }

    /// Writable `/out` is NOT a host bind mount (issue #9): it is a tmpfs capped
    /// at `out_bytes` / `out_inodes` (charged to the container's memory cgroup),
    /// owned by the job user. The host gets positions.csv back over a framed
    /// stderr record written by a wrapper after the command exits.
    fn out_tmpfs(req: &SandboxRequest) -> Option<(String, String)> {
        req.mounts
            .iter()
            .find(|m| m.container == "/out" && !m.read_only)?;
        let ug = run_as_user(req);
        let (u, g) = ug.split_once(':').unwrap_or(("10001", "10001"));
        Some((
            "/out".into(),
            format!(
                "rw,noexec,nosuid,nodev,size={},nr_inodes={},uid={u},gid={g},mode=0700",
                req.limits.out_bytes, req.limits.out_inodes
            ),
        ))
    }

    pub fn host_config(req: &SandboxRequest) -> HostConfig {
        let mem = (req.limits.memory_mb * 1024 * 1024) as i64;
        HostConfig {
            network_mode: Some("none".into()),
            readonly_rootfs: Some(true),
            privileged: Some(false),
            cap_drop: Some(vec!["ALL".into()]),
            security_opt: Some(vec![
                "no-new-privileges:true".into(),
                format!("seccomp={}", SECCOMP_PROFILE),
            ]),
            pids_limit: Some(req.limits.pids),
            memory: Some(mem),
            memory_swap: Some(mem),
            nano_cpus: Some((req.limits.cpu_cores * 1e9) as i64),
            binds: Some(
                req.mounts
                    .iter()
                    .filter(|m| m.container != "/out" || m.read_only)
                    .map(|m| {
                        format!(
                            "{}:{}:{}",
                            m.host.display(),
                            m.container,
                            if m.read_only { "ro" } else { "rw" }
                        )
                    })
                    .collect(),
            ),
            tmpfs: Some(HashMap::from_iter(
                [("/tmp".to_string(), "rw,noexec,nosuid,size=64m".to_string())]
                    .into_iter()
                    .chain(Self::out_tmpfs(req)),
            )),
            // the daemon's own copy of the logs is bounded per container
            log_config: Some(bollard::models::HostConfigLogConfig {
                typ: Some("json-file".into()),
                config: Some(HashMap::from([
                    ("max-size".to_string(), format!("{}", req.limits.log_bytes)),
                    ("max-file".to_string(), "1".to_string()),
                ])),
            }),
            ipc_mode: Some("private".into()),
            // hide host clocks / boot time (btime) / uptime from the strategy
            masked_paths: Some(
                [
                    "/proc/stat",
                    "/proc/uptime",
                    "/proc/loadavg",
                    "/proc/timer_list",
                    "/proc/sched_debug",
                    "/proc/kcore",
                    "/proc/keys",
                    "/proc/latency_stats",
                    "/proc/acpi",
                    "/proc/scsi",
                    "/sys/firmware",
                    "/proc/interrupts",
                    "/proc/driver/rtc",
                ]
                .map(String::from)
                .to_vec(),
            ),
            ..Default::default()
        }
    }
}

#[async_trait]
impl SandboxExecutor for DockerSandboxExecutor {
    fn name(&self) -> &'static str {
        "docker"
    }
    fn hardened(&self) -> bool {
        true
    }
    async fn runner_identity(&self, image: &str) -> Option<String> {
        let i = self.docker.inspect_image(image).await.ok()?;
        let ver = i
            .config
            .and_then(|c| c.labels)
            .and_then(|l| l.get("cmsq.runner.version").cloned())
            .unwrap_or_else(|| "none".into());
        Some(format!(
            "{}|cmsq.runner.version={ver}",
            i.id.unwrap_or_default()
        ))
    }
    async fn execute(&self, req: &SandboxRequest) -> Result<SandboxResult, SandboxError> {
        validate(req)?;
        let host = Self::host_config(req);
        let policy = serde_json::json!({
            "backend": "docker", "network_mode": "none", "readonly_rootfs": true, "cap_drop": ["ALL"],
            "no_new_privileges": true, "seccomp": "cmsq-runner (docker default minus wall-clock syscalls)", "user": run_as_user(req), "memory_mb": req.limits.memory_mb, "swap": false,
            "cpu_cores": req.limits.cpu_cores, "pids": req.limits.pids, "timeout_secs": req.limits.timeout_secs,
            "mounts": req.mounts, "docker_socket_mounted": false,
            "out": format!("tmpfs size={} nr_inodes={}", req.limits.out_bytes, req.limits.out_inodes), "log_budget_bytes": req.limits.log_bytes,
        });
        let name = format!("cmsq-{}", req.id);
        let out_host = req
            .mounts
            .iter()
            .find(|m| m.container == "/out" && !m.read_only)
            .map(|m| m.host.clone());
        let nonce = uuid::Uuid::new_v4().simple().to_string();
        let entry = match &out_host {
            Some(_) => wrap_command(&req.command, &nonce),
            None => req.command.clone(),
        };
        let cfg = Config {
            image: Some(req.image.clone()),
            entrypoint: Some(entry),
            cmd: Some(vec![]),
            env: Some(req.env.iter().map(|(k, v)| format!("{k}={v}")).collect()),
            user: Some(run_as_user(req)),
            working_dir: Some("/tmp".into()),
            network_disabled: Some(true),
            host_config: Some(host),
            labels: Some(HashMap::from([("cmsq.job".to_string(), req.id.clone())])),
            ..Default::default()
        };
        let created = self
            .docker
            .create_container(
                Some(CreateContainerOptions {
                    name: name.clone(),
                    platform: None,
                }),
                cfg,
            )
            .await
            .map_err(|e| SandboxError::Execution(format!("create: {e}")))?;
        let id = created.id;
        let mut cleanup = ContainerCleanup {
            docker: self.docker.clone(),
            id: id.clone(),
            armed: true,
        };
        let t0 = Instant::now();
        let budget = req.limits.log_bytes as usize;
        let (mut out_b, mut err_b): (Vec<u8>, Vec<u8>) = (vec![], vec![]);
        let mut over = false;
        let run = async {
            self.docker
                .start_container::<String>(&id, None)
                .await
                .map_err(|e| SandboxError::Execution(format!("start: {e}")))?;
            // follow the logs while the job runs; the stream ends when it exits
            let mut logs = self.docker.logs(
                &id,
                Some(LogsOptions::<String> {
                    follow: true,
                    stdout: true,
                    stderr: true,
                    ..Default::default()
                }),
            );
            while let Some(Ok(l)) = logs.next().await {
                let (buf, msg) = match l {
                    LogOutput::StdOut { message } => (&mut out_b, message),
                    LogOutput::StdErr { message } => (&mut err_b, message),
                    _ => continue,
                };
                buf.extend_from_slice(&msg);
                if out_b.len() + err_b.len() > budget {
                    over = true;
                    let _ = self
                        .docker
                        .kill_container(&id, Some(KillContainerOptions { signal: "SIGKILL" }))
                        .await;
                    break;
                }
            }
            let mut w = self
                .docker
                .wait_container(&id, None::<WaitContainerOptions<String>>);
            let mut code = -1;
            while let Some(r) = w.next().await {
                match r {
                    Ok(x) => code = x.status_code,
                    Err(bollard::errors::Error::DockerContainerWaitError { code: c, .. }) => {
                        code = c
                    }
                    Err(e) => return Err(SandboxError::Execution(format!("wait: {e}"))),
                }
            }
            Ok::<i64, SandboxError>(code)
        };
        let (outcome, exit_code) =
            match tokio::time::timeout(Duration::from_secs(req.limits.timeout_secs), run).await {
                Ok(Ok(code)) => {
                    let oom = self
                        .docker
                        .inspect_container(&id, None)
                        .await
                        .ok()
                        .and_then(|i| i.state)
                        .and_then(|s| s.oom_killed)
                        .unwrap_or(false);
                    (
                        if oom {
                            Outcome::OomKilled
                        } else {
                            Outcome::Exited
                        },
                        code,
                    )
                }
                Ok(Err(e)) => {
                    let _ = self
                        .docker
                        .remove_container(
                            &id,
                            Some(RemoveContainerOptions {
                                force: true,
                                ..Default::default()
                            }),
                        )
                        .await;
                    return Err(e);
                }
                Err(_) => {
                    let _ = self
                        .docker
                        .kill_container(&id, Some(KillContainerOptions { signal: "SIGKILL" }))
                        .await;
                    (Outcome::TimedOut, 137)
                }
            };
        let duration_ms = t0.elapsed().as_millis() as u64;
        let outcome = if over {
            Outcome::QuotaExceeded
        } else {
            outcome
        };
        // positions.csv comes back framed on stderr; everything else is discarded
        let (err_b, framed) = take_frame(&err_b, &nonce);
        let mut copy_result = Ok(());
        if let (Some(dir), Some(body), Outcome::Exited) = (&out_host, framed, &outcome) {
            if body.len() <= super::POSITIONS_CAP {
                copy_result = std::fs::write(dir.join("positions.csv"), body);
            }
        }
        let cap = |b: &[u8]| String::from_utf8_lossy(&b[..b.len().min(OUTPUT_CAP)]).into_owned();
        let (stdout, stderr) = (cap(&out_b), cap(&err_b));
        if self
            .docker
            .remove_container(
                &id,
                Some(RemoveContainerOptions {
                    force: true,
                    ..Default::default()
                }),
            )
            .await
            .is_ok()
        {
            cleanup.armed = false;
        }
        copy_result.map_err(SandboxError::Io)?;
        Ok(SandboxResult {
            id: req.id.clone(),
            outcome,
            exit_code,
            stdout,
            stderr,
            duration_ms,
            policy,
        })
    }
}

/// `sh -c` wrapper: run the command, then (whatever it did) emit
/// /out/positions.csv between nonce markers on stderr and keep its exit code.
pub fn wrap_command(cmd: &[String], nonce: &str) -> Vec<String> {
    let script = format!(
        "\"$@\"; rc=$?; if [ -f /out/positions.csv ] && [ ! -L /out/positions.csv ]; then printf '\\n@@CMSQ-BEGIN-{nonce}@@\\n' >&2; cat /out/positions.csv >&2; printf '\\n@@CMSQ-END-{nonce}@@\\n' >&2; fi; exit $rc"
    );
    let mut v = vec![
        "/bin/sh".to_string(),
        "-c".into(),
        script,
        "cmsq-wrap".into(),
    ];
    v.extend(cmd.iter().cloned());
    v
}

/// Split the LAST framed record out of stderr. Returns (stderr without it, body).
pub fn take_frame(err: &[u8], nonce: &str) -> (Vec<u8>, Option<Vec<u8>>) {
    let b = format!("\n@@CMSQ-BEGIN-{nonce}@@\n");
    let e = format!("\n@@CMSQ-END-{nonce}@@\n");
    let find = |hay: &[u8], pat: &[u8]| hay.windows(pat.len()).rposition(|w| w == pat);
    let Some(i) = find(err, b.as_bytes()) else {
        return (err.to_vec(), None);
    };
    let body_start = i + b.len();
    let Some(j) = find(&err[body_start..], e.as_bytes()) else {
        return (err.to_vec(), None);
    };
    let body = err[body_start..body_start + j].to_vec();
    let mut rest = err[..i].to_vec();
    rest.extend_from_slice(&err[body_start + j + e.len()..]);
    (rest, Some(body))
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn host_config_is_hardened() {
        let req = SandboxRequest {
            id: "t".into(),
            image: "x".into(),
            command: vec![],
            env: vec![],
            mounts: vec![Mount {
                host: "/tmp/d".into(),
                container: "/data".into(),
                read_only: true,
            }],
            limits: SandboxLimits::default(),
        };
        let h = DockerSandboxExecutor::host_config(&req);
        assert_eq!(h.network_mode.as_deref(), Some("none"));
        assert_eq!(h.readonly_rootfs, Some(true));
        assert_eq!(h.privileged, Some(false));
        assert_eq!(h.cap_drop, Some(vec!["ALL".to_string()]));
        assert_eq!(h.memory, h.memory_swap);
        assert_eq!(h.binds.unwrap(), vec!["/tmp/d:/data:ro".to_string()]);
    }
    #[test]
    fn out_is_a_capped_tmpfs_and_logs_are_capped() {
        let mut req = SandboxRequest {
            id: "t".into(),
            image: "x".into(),
            command: vec!["python3".into()],
            env: vec![],
            mounts: vec![Mount {
                host: "/tmp".into(),
                container: "/out".into(),
                read_only: false,
            }],
            limits: SandboxLimits::default(),
        };
        req.limits.out_bytes = 4096;
        let h = DockerSandboxExecutor::host_config(&req);
        assert!(h.binds.unwrap().is_empty(), "no host bind for /out");
        let t = h.tmpfs.unwrap();
        assert!(
            t["/out"].contains("size=4096") && t["/out"].contains("nr_inodes=16"),
            "{t:?}"
        );
        let lc = h.log_config.unwrap();
        assert_eq!(lc.config.unwrap()["max-file"], "1");
    }
    #[test]
    fn frame_roundtrip_takes_the_last_record() {
        let n = "abc";
        let fake = b"x\n@@CMSQ-BEGIN-abc@@\nFORGED\n@@CMSQ-END-abc@@\n".to_vec();
        let mut err = b"log line".to_vec();
        err.extend_from_slice(&fake);
        err.extend_from_slice(b"\n@@CMSQ-BEGIN-abc@@\ndate,position\n@@CMSQ-END-abc@@\n");
        let (rest, body) = take_frame(&err, n);
        assert_eq!(body.unwrap(), b"date,position");
        assert!(String::from_utf8_lossy(&rest).contains("FORGED"));
        assert_eq!(take_frame(b"no frame", n).1, None);
    }
}
